import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
// Warp-level reduction
__inline__ __device__ float warpReduceSum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}
// Number of output rows handled cooperatively by a single CTA. The B vector
// (which is identical for every row) is staged into shared memory once per
// K-tile and reused across all TILE_M rows, cutting global-memory traffic
// for B by a factor of TILE_M compared to a one-row-per-block kernel.
constexpr int TILE_M = 8;
constexpr int TILE_K = 2048; // floats staged in shared memory per iteration
constexpr int SPLIT_K = 32; // split the huge K dimension across blocks for parallelism (increased to raise grid size and better fill SM occupancy, addressing observed low achieved occupancy)
constexpr int VEC = 4; // number of floats per float4 vectorized load
__device__ __forceinline__ void cp_async_cg_16(void* smem_ptr, const void* gmem_ptr) {
    unsigned smem_int_ptr = static_cast<unsigned>(__cvta_generic_to_shared(smem_ptr));
    asm volatile(
        "cp.async.cg.shared.global [%0], [%1], 16;\n"
        :: "r"(smem_int_ptr), "l"(gmem_ptr));
}
__device__ __forceinline__ void cp_async_commit_group() {
    asm volatile("cp.async.commit_group;\n" ::: "memory");
}
template <int N>
__device__ __forceinline__ void cp_async_wait_group() {
    asm volatile("cp.async.wait_group %0;\n" :: "n"(N) : "memory");
}
__device__ __forceinline__ void loadBTileAsync(
    const float* __restrict__ B, float* __restrict__ sBbuf,
    int kBase, int kTile, int tid, int nThreads)
{
    int kTileVec = kTile / VEC;
    const float4* __restrict__ B4 = reinterpret_cast<const float4*>(B + kBase);
    float4* __restrict__ sB4 = reinterpret_cast<float4*>(sBbuf);
    for (int i = tid; i < kTileVec; i += nThreads) {
        cp_async_cg_16(&sB4[i], &B4[i]);
    }
    for (int i = kTileVec * VEC + tid; i < kTile; i += nThreads) {
        sBbuf[i] = B[kBase + i];
    }
}
template <typename T>
__global__ void matvec_kernel(
    const T* __restrict__ A,
    const T* __restrict__ B,
    T* __restrict__ partialC,
    int M, int K)
{
    const int rowBase = blockIdx.x * TILE_M;
    const int tid = threadIdx.x;
    const int nThreads = blockDim.x;
    const int splitK = gridDim.y;
    const int splitId = blockIdx.y;
    int chunk = (K + splitK - 1) / splitK;
    chunk = ((chunk + 3) / 4) * 4;
    int kStart = splitId * chunk;
    int kEnd = (K < kStart + chunk) ? K : (kStart + chunk);
    // Double-buffered shared memory staging of the B tile using cp.async
    // (asynchronous global->shared copies). While the current tile is
    // being consumed for the dot-product accumulation, the next tile's
    // copy is already in flight in the background, truly overlapping
    // memory latency with compute instead of relying purely on
    // instruction-level scheduling of ordinary loads.
    __shared__ float sB[2][TILE_K];
    float acc[TILE_M];
#pragma unroll
    for (int r = 0; r < TILE_M; r++) acc[r] = 0.0f;
    int curBuf = 0;
    if (kStart < kEnd) {
        int kTile0 = (kEnd - kStart < TILE_K) ? (kEnd - kStart) : TILE_K;
        loadBTileAsync(B, sB[curBuf], kStart, kTile0, tid, nThreads);
        cp_async_commit_group();
        cp_async_wait_group<0>();
    }
    __syncthreads();
    for (int kBase = kStart; kBase < kEnd; kBase += TILE_K) {
        int kTile = (kEnd - kBase < TILE_K) ? (kEnd - kBase) : TILE_K;
        int kTileVec = kTile / VEC;
        int nextBase = kBase + TILE_K;
        int nextBuf = curBuf ^ 1;
        bool hasNext = (nextBase < kEnd);
        if (hasNext) {
            int nextTile = (kEnd - nextBase < TILE_K) ? (kEnd - nextBase) : TILE_K;
            // Prefetch the next B tile into the other buffer asynchronously
            // while the compute below consumes the current buffer.
            loadBTileAsync(B, sB[nextBuf], nextBase, nextTile, tid, nThreads);
            cp_async_commit_group();
        }
        // Every thread accumulates partial dot products for all TILE_M rows
        // using the shared B tile. A is read with vectorized float4 loads
        // (coalesced across threads) to maximize memory throughput, since A
        // reads dominate runtime for this large-K workload.
        float4* __restrict__ sB4 = reinterpret_cast<float4*>(sB[curBuf]);
        for (int iv = tid; iv < kTileVec; iv += nThreads) {
            float4 bVal4 = sB4[iv];
            int kIdxBase = kBase + iv * VEC;
#pragma unroll
            for (int r = 0; r < TILE_M; r++) {
                int row = rowBase + r;
                if (row < M) {
                    const float4* __restrict__ Arow4 =
                        reinterpret_cast<const float4*>(A + (size_t)row * K + kIdxBase);
                    float4 aVal4 = *Arow4;
                    acc[r] += aVal4.x * bVal4.x + aVal4.y * bVal4.y +
                              aVal4.z * bVal4.z + aVal4.w * bVal4.w;
                }
            }
        }
        for (int i = kTileVec * VEC + tid; i < kTile; i += nThreads) {
            float bVal = sB[curBuf][i];
            int kIdx = kBase + i;
#pragma unroll
            for (int r = 0; r < TILE_M; r++) {
                int row = rowBase + r;
                if (row < M) {
                    acc[r] += static_cast<float>(A[(size_t)row * K + kIdx]) * bVal;
                }
            }
        }
        if (hasNext) {
            cp_async_wait_group<0>();
        }
        __syncthreads();
        curBuf = nextBuf;
    }
    // Block-wide reduction per row: warp reduce then combine across warps.
    __shared__ float warpSums[TILE_M][32];
    int lane = tid & 31;
    int warpId = tid >> 5;
#pragma unroll
    for (int r = 0; r < TILE_M; r++) {
        float val = warpReduceSum(acc[r]);
        if (lane == 0) {
            warpSums[r][warpId] = val;
        }
    }
    __syncthreads();
    int numWarps = (nThreads + 31) >> 5;
    if (warpId == 0) {
#pragma unroll
        for (int r = 0; r < TILE_M; r++) {
            float val = (lane < numWarps) ? warpSums[r][lane] : 0.0f;
            val = warpReduceSum(val);
            if (lane == 0) {
                int row = rowBase + r;
                if (row < M) {
                    partialC[(size_t)splitId * M + row] = val;
                }
            }
        }
    }
}
template <typename T>
__global__ void reduce_splits_kernel(
    const T* __restrict__ partialC,
    T* __restrict__ C,
    int M, int splitK)
{
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < M) {
        float sum = 0.0f;
        for (int s = 0; s < splitK; s++) {
            sum += partialC[(size_t)s * M + row];
        }
        C[row] = sum;
    }
}
torch::Tensor matvec_forward(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2, "A must be 2D (M, K)");
    TORCH_CHECK(B.dim() == 2 && B.size(1) == 1, "B must be 2D (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Inner dimensions must match");
    TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
                "Expect float32 tensors");
    auto A_c = A.contiguous();
    auto B_c = B.contiguous();
    int M = (int)A_c.size(0);
    int K = (int)A_c.size(1);
    auto C = torch::empty({M, 1}, A.options());
    auto partialC = torch::empty({(int64_t)SPLIT_K, (int64_t)M}, A.options());
    const float* ptrA = A_c.data_ptr<float>();
    const float* ptrB = B_c.data_ptr<float>();
    float* ptrC = C.data_ptr<float>();
    float* ptrPartial = partialC.data_ptr<float>();
    int threads = 256;
    dim3 block(threads);
    int gridBlocks = (M + TILE_M - 1) / TILE_M;
    dim3 grid(gridBlocks, SPLIT_K);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    matvec_kernel<float><<<grid, block, 0, stream>>>(ptrA, ptrB, ptrPartial, M, K);
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "matvec_kernel launch failed: ", cudaGetErrorString(err));
    int reduceThreads = 256;
    int reduceBlocks = (M + reduceThreads - 1) / reduceThreads;
    reduce_splits_kernel<float><<<reduceBlocks, reduceThreads, 0, stream>>>(ptrPartial, ptrC, M, SPLIT_K);
    err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "reduce_splits_kernel launch failed: ", cudaGetErrorString(err));
    return C;
}
"""

matvec_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["matvec_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom
    CuTe-based CUDA kernel. Each CUDA block computes the dot product for
    one row of A with the vector B, using vectorized (float4) loads and
    a warp-shuffle + shared-memory tree reduction across the block.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = matvec_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matvec_forward(A, B)

